function mergeSort(a) {
  if (a.length <= 1) return a;
  const mid = a.length >> 1;
  const left = mergeSort(a.slice(0, mid));
  const right = mergeSort(a.slice(mid));
  const out = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    out.push(left[i] <= right[j] ? left[i++] : right[j++]); // <= keeps it stable
  }
  return out.concat(left.slice(i), right.slice(j));
}

// Quickselect: kth smallest (0-based), expected O(n)
function quickselect(a, k) {
  let lo = 0, hi = a.length - 1;
  while (lo <= hi) {
    const r = lo + Math.floor(Math.random() * (hi - lo + 1));
    [a[r], a[hi]] = [a[hi], a[r]];           // random pivot to the end
    let i = lo;
    for (let j = lo; j < hi; j++) if (a[j] < a[hi]) { [a[i], a[j]] = [a[j], a[i]]; i++; }
    [a[i], a[hi]] = [a[hi], a[i]];            // pivot to its final index i
    if (i === k) return a[i];
    if (i < k) lo = i + 1; else hi = i - 1;   // keep ONE side only
  }
}

static void mergeSort(int[] a, int[] tmp, int lo, int hi) {
    if (hi - lo < 1) return;
    int mid = lo + (hi - lo) / 2;
    mergeSort(a, tmp, lo, mid);
    mergeSort(a, tmp, mid + 1, hi);
    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi) tmp[k++] = a[j++];
    System.arraycopy(tmp, lo, a, lo, hi - lo + 1);
}

int partitionLomuto(vector<int>& a, int lo, int hi) {
    swap(a[lo + rand() % (hi - lo + 1)], a[hi]);   // random pivot
    int i = lo;
    for (int j = lo; j < hi; j++)
        if (a[j] < a[hi]) swap(a[i++], a[j]);
    swap(a[i], a[hi]);
    return i;                                       // pivot's final index
}
void quickSort(vector<int>& a, int lo, int hi) {
    if (lo >= hi) return;
    int p = partitionLomuto(a, lo, hi);
    quickSort(a, lo, p - 1);
    quickSort(a, p + 1, hi);
}

// Stable counting sort for integers in [0, k]
function countingSort(a, k) {
  const count = new Array(k + 1).fill(0);
  for (const v of a) count[v]++;
  for (let v = 1; v <= k; v++) count[v] += count[v - 1]; // prefix sums
  const out = new Array(a.length);
  for (let i = a.length - 1; i >= 0; i--) out[--count[a[i]]] = a[i]; // right to left = stable
  return out;
}

// Top K Frequent in O(n) with frequency buckets
function topKFrequent(nums, k) {
  const freq = new Map();
  for (const x of nums) freq.set(x, (freq.get(x) || 0) + 1);
  const buckets = Array.from({ length: nums.length + 1 }, () => []);
  for (const [x, f] of freq) buckets[f].push(x);
  const out = [];
  for (let f = buckets.length - 1; f > 0 && out.length < k; f--) out.push(...buckets[f]);
  return out.slice(0, k);
}

static int[] countingSort(int[] a, int k) {
    int[] count = new int[k + 1], out = new int[a.length];
    for (int v : a) count[v]++;
    for (int v = 1; v <= k; v++) count[v] += count[v - 1];
    for (int i = a.length - 1; i >= 0; i--) out[--count[a[i]]] = a[i];
    return out;
}
